namespace ModernHost {
public sealed class ReadOnlySqlite : IDisposable {
    private IntPtr db;
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_open_v2(byte[] file,out IntPtr db,int flags,IntPtr vfs);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_close(IntPtr db);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_busy_timeout(IntPtr db,int ms);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_prepare_v2(IntPtr db,byte[] sql,int bytes,out IntPtr statement,IntPtr tail);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_step(IntPtr statement);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_finalize(IntPtr statement);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_column_count(IntPtr statement);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern IntPtr sqlite3_column_text(IntPtr statement,int column);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]static extern int sqlite3_column_bytes(IntPtr statement,int column);
    public ReadOnlySqlite(string file) {if(sqlite3_open_v2(Encoding.UTF8.GetBytes(file+"\0"),out db,1,IntPtr.Zero)!=0){Dispose();throw new InvalidOperationException("无法只读打开 OpenCode 数据库");}sqlite3_busy_timeout(db,2000);}
    public List<string[]> Query(string sql) {IntPtr statement; if(sqlite3_prepare_v2(db,Encoding.UTF8.GetBytes(sql+"\0"),-1,out statement,IntPtr.Zero)!=0)throw new InvalidOperationException("OpenCode 数据格式暂不支持此查询");try{var rows=new List<string[]>();int result;while((result=sqlite3_step(statement))==100){var row=new string[sqlite3_column_count(statement)];for(int i=0;i<row.Length;i++){IntPtr value=sqlite3_column_text(statement,i);int length=sqlite3_column_bytes(statement,i);if(value!=IntPtr.Zero){byte[] bytes=new byte[length];Marshal.Copy(value,bytes,0,length);row[i]=Encoding.UTF8.GetString(bytes);}}rows.Add(row);if(rows.Count>500000)throw new InvalidOperationException("OpenCode 记录过多，请缩小查询范围");}if(result!=101)throw new InvalidOperationException("OpenCode 数据库忙，请稍后刷新");return rows;}finally{sqlite3_finalize(statement);}}
    public void Dispose(){if(db!=IntPtr.Zero){sqlite3_close(db);db=IntPtr.Zero;}}
}
public class OpenCodeCredential {public string Id,Provider,Label,Value;public bool Active;}
public class OpenCodeRecord {public string Provider,Model;public long Time;public double Input,Output,Reasoning,Read,Write,Cost;public double Total{get{return Input+Output+Reasoning+Read+Write;}}}
public sealed class OpenCodeService : IDisposable {
    public static string DataDirectory {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".local","share","opencode");}}
    public static string DatabasePath {get{return Path.Combine(DataDirectory,"opencode.db");}}
    private readonly object cacheGate=new object();private string signature;private List<OpenCodeRecord> records;
    private readonly string database,backupDirectory;
    private readonly Func<string,string,object,Task<Dictionary<string,object>>> apiOverride;
    private readonly Func<List<OpenCodeCredential>> credentialOverride;
    public OpenCodeService():this(null,null,null,null){}
    public OpenCodeService(string databasePath=null,Func<string,string,object,Task<Dictionary<string,object>>> api=null,Func<List<OpenCodeCredential>> credentials=null,string backups=null){database=databasePath??DatabasePath;backupDirectory=backups??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"commandcode-account-manager");apiOverride=api;credentialOverride=credentials;}
    private readonly SemaphoreSlim serverGate=new SemaphoreSlim(1);private Process server;private HttpClient local;
    private Timer idleTimer;private int apiCalls;private bool disposed;
    private void StopServer(){if(local!=null){local.Dispose();local=null;}if(server!=null){try{if(!server.HasExited)server.Kill();}catch(InvalidOperationException){}server.Dispose();server=null;}}
    private void StartIdleTimer(){if(idleTimer==null)idleTimer=new Timer(state=>{if(Volatile.Read(ref apiCalls)!=0||!serverGate.Wait(0))return;try{if(Volatile.Read(ref apiCalls)==0)StopServer();}finally{serverGate.Release();}},null,Timeout.Infinite,Timeout.Infinite);idleTimer.Change(60000,Timeout.Infinite);}
    private static readonly HttpClient remote=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(20)};
    public static bool IsOpenCode(Account account){return account.Platform=="opencode";}
    public static string ProviderName(string id){switch(id){case "opencode":return "OpenCode Zen";case "opencode-go":return "OpenCode Go";case "openai":return "OpenAI";case "anthropic":return "Anthropic";case "google":return "Google";case "github-copilot":return "GitHub Copilot";case "deepseek":return "DeepSeek";case "openrouter":return "OpenRouter";default:return id;}}
    public static string ValidateProvider(string id){if(!Regex.IsMatch(id??"",@"^[a-zA-Z0-9_.-]{1,128}$"))throw new InvalidOperationException("服务商标识格式不正确");return id;}
    public static Dictionary<string,object> ParseValue(string value){var result=new JavaScriptSerializer{MaxJsonLength=65536}.Deserialize<Dictionary<string,object>>(value);string type=Core.Text(result,"type");if(type=="api")result["type"]="key";if(type!="api"&&type!="key"&&type!="oauth"&&type!="external")throw new InvalidOperationException("不支持的 OpenCode 凭据类型");if((type=="api"||type=="key")&&string.IsNullOrWhiteSpace(Core.Text(result,"key")))throw new InvalidOperationException("请填写有效 API Key");return result;}
    public static string KeyValue(string key){if(string.IsNullOrWhiteSpace(key)||key.Length>8192||key.Contains("\r")||key.Contains("\n"))throw new InvalidOperationException("请填写有效 API Key");return new JavaScriptSerializer().Serialize(new{type="key",key=key.Trim()});}
    public static string Fingerprint(string value){var data=ParseValue(value);string type=Core.Text(data,"type");return type+"|"+(type=="key"?Core.Text(data,"key"):type=="oauth"?(string.IsNullOrEmpty(Core.Text(data,"refresh"))?Core.Text(data,"access"):Core.Text(data,"refresh")):new JavaScriptSerializer().Serialize(data));}
    public static List<OpenCodeCredential> Credentials(){return ReadCredentials(DatabasePath,Path.Combine(DataDirectory,"auth.json"));}
    public static List<OpenCodeCredential> ReadCredentials(string databasePath,string authPath){var result=new List<OpenCodeCredential>();if(File.Exists(databasePath)){using(var db=new ReadOnlySqlite(databasePath)){if(db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name='credential'").Count>0){foreach(var row in db.Query("SELECT id,integration_id,label,value,active FROM credential ORDER BY integration_id,active DESC,time_created DESC,id DESC")){if(string.IsNullOrEmpty(row[1]))continue;result.Add(new OpenCodeCredential{Id=row[0],Provider=ValidateProvider(row[1]),Label=row[2],Value=new JavaScriptSerializer().Serialize(ParseValue(row[3])),Active=row[4]=="1"});}}}if(result.Count>0){foreach(var group in result.GroupBy(item=>item.Provider)){bool first=true;foreach(var item in group){item.Active=first;first=false;}}return result;}}string file=authPath;if(File.Exists(file)){var json=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(file));foreach(var item in json){string value=new JavaScriptSerializer().Serialize(item.Value);result.Add(new OpenCodeCredential{Provider=ValidateProvider(item.Key),Label=ProviderName(item.Key),Value=new JavaScriptSerializer().Serialize(ParseValue(value)),Active=true});}}return result;}
    private static double Number(string value){double result;return double.TryParse(value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out result)&&!double.IsNaN(result)&&!double.IsInfinity(result)?Math.Max(0,result):0;}
    public List<OpenCodeRecord> Records(){lock(cacheGate){if(!File.Exists(database))throw new InvalidOperationException("尚未找到 OpenCode 本地用量数据库");var file=new FileInfo(database);var wal=new FileInfo(database+"-wal");string stamp=file.Length+"|"+file.LastWriteTimeUtc.Ticks+"|"+(wal.Exists?wal.Length+"|"+wal.LastWriteTimeUtc.Ticks:"");if(signature==stamp&&records!=null)return records;using(var db=new ReadOnlySqlite(database)){var tables=db.Query("SELECT name FROM sqlite_master WHERE type='table'").Select(row=>row[0]).ToArray();var queries=new List<string>();string fields="m.time_created,COALESCE(json_extract(m.data,'$.providerID'),json_extract(m.data,'$.model.providerID')),COALESCE(json_extract(m.data,'$.modelID'),json_extract(m.data,'$.model.id')),json_extract(m.data,'$.tokens.input'),json_extract(m.data,'$.tokens.output'),json_extract(m.data,'$.tokens.reasoning'),json_extract(m.data,'$.tokens.cache.read'),json_extract(m.data,'$.tokens.cache.write'),json_extract(m.data,'$.cost')";
    if(tables.Contains("session_message"))queries.Add("SELECT "+fields+" FROM session_message m JOIN session_v2 s ON s.id=m.session_id WHERE m.type='assistant' AND (s.fork_session_id IS NULL OR m.time_created>=s.time_created)");
    if(tables.Contains("message"))queries.Add("SELECT "+fields+" FROM message m WHERE json_extract(m.data,'$.role')='assistant'"+(tables.Contains("session_message")?" AND NOT EXISTS(SELECT 1 FROM session_message v WHERE v.id=m.id)":""));if(queries.Count==0)throw new InvalidOperationException("当前 OpenCode 数据库没有受支持的用量记录表");records=db.Query(string.Join(" UNION ALL ",queries)).Where(row=>!string.IsNullOrEmpty(row[1])).Select(row=>new OpenCodeRecord{Time=(long)Number(row[0]),Provider=row[1],Model=row[2],Input=Number(row[3]),Output=Number(row[4]),Reasoning=Number(row[5]),Read=Number(row[6]),Write=Number(row[7]),Cost=Number(row[8])}).ToList();signature=stamp;return records;}}}
    private static WindowUsage Window(Dictionary<string,object> usage,string name){var data=Core.Object(Core.Value(usage,name));double? percent=Core.Number(data,"percent");return data.Count==0?null:new WindowUsage{Used=percent,Cap=100,ResetAt=Core.Text(data,"resetsAt")};}
    private static async Task<Dictionary<string,object>> Remote(string url,string key){try{using(var request=new HttpRequestMessage(HttpMethod.Get,url)){request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",key);request.Headers.UserAgent.ParseAdd("CommandCodeManager/1.0");using(var response=await remote.SendAsync(request)){if(!response.IsSuccessStatusCode)throw new ApiFailure((int)response.StatusCode);return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(await response.Content.ReadAsStringAsync());}}}catch(TaskCanceledException){throw new InvalidOperationException("OpenCode 用量查询超时，请稍后刷新");}catch(HttpRequestException){throw new InvalidOperationException("无法连接 OpenCode 服务商接口，请检查网络");}}
    public async Task<AccountData> Fetch(Account account,string credential){ValidateProvider(account.ProviderId);var value=ParseValue(credential);var data=new AccountData{UserId=account.OpenCodeCredentialId??account.Id,OrgId=account.ProviderId,UserName=string.IsNullOrWhiteSpace(Core.Text(Core.Object(Core.Value(value,"metadata")),"email"))?ProviderName(account.ProviderId):Core.Text(Core.Object(Core.Value(value,"metadata")),"email"),Email=ProviderName(account.ProviderId),Plan=account.ProviderId=="opencode-go"?"opencode-go":account.ProviderId=="opencode"?"opencode-zen":"external-api",Status="configured",FetchedAt=DateTimeOffset.UtcNow.ToString("o"),UsageUnit="percent",UsageSource="本机 OpenCode 记录",UsageNote="本机服务商历史统计，包含该服务商所有账号；旧记录未保存账号身份，不能按账号回溯。",Limited=null};string key=Core.Text(value,"key");
    if(account.ProviderId=="opencode-go"&&!string.IsNullOrEmpty(key)){var usage=Core.Object(Core.Value(await Remote("https://opencode.ai/zen/go/v1/usage",key),"usage"));data.FiveHour=Window(usage,"rolling");data.Weekly=Window(usage,"weekly");var monthly=Window(usage,"monthly");if(monthly!=null){data.MonthlyUsed=monthly.Used;data.MonthlyTotal=monthly.Cap;data.MonthlyResetAt=monthly.ResetAt;}data.Limited=true;data.Status="active";}
    else if(account.ProviderId=="openrouter"&&!string.IsNullOrEmpty(key)){var credits=Core.Object(Core.Value(await Remote("https://openrouter.ai/api/v1/credits",key),"data"));double? total=Core.Number(credits,"total_credits"),used=Core.Number(credits,"total_usage");if(total.HasValue&&used.HasValue)data.Remaining=total-used;data.Status="active";}
    else if(account.ProviderId=="deepseek"&&!string.IsNullOrEmpty(key)){var response=await Remote("https://api.deepseek.com/user/balance",key);var balances=Core.Value(response,"balance_infos") as System.Collections.IEnumerable;if(balances!=null)foreach(object balance in balances){var item=Core.Object(balance);if(Core.Text(item,"currency")=="USD"){double amount;if(double.TryParse(Core.Text(item,"total_balance"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out amount))data.Remaining=amount;}}data.Status="active";}
    try{var rows=await Task.Run(()=>Records().Where(row=>row.Provider==account.ProviderId).ToArray());data.TotalTokens=rows.Sum(row=>row.Total);data.InputTokens=rows.Sum(row=>row.Input);data.OutputTokens=rows.Sum(row=>row.Output);data.ReasoningTokens=rows.Sum(row=>row.Reasoning);data.CacheReadTokens=rows.Sum(row=>row.Read);data.CacheWriteTokens=rows.Sum(row=>row.Write);data.RequestCount=rows.Length;data.PeriodCost=rows.Sum(row=>row.Cost);data.Models=rows.GroupBy(row=>row.Model).Select(group=>new ModelUsage{Model=group.Key,Tokens=group.Sum(row=>row.Total),Input=group.Sum(row=>row.Input),Output=group.Sum(row=>row.Output),Reasoning=group.Sum(row=>row.Reasoning),CacheRead=group.Sum(row=>row.Read),CacheWrite=group.Sum(row=>row.Write),Requests=group.Count(),Cost=group.Sum(row=>row.Cost)}).OrderByDescending(model=>model.Tokens).ToArray();}catch(Exception error){data.TokenError=error.Message;}return data;}
    public HistoryWindow History(Account account,HistoryQuery query){int pages;var boundaries=TokenHistoryCache.Dates(query,DateTimeOffset.UtcNow,out pages);var records=Records().Where(row=>row.Provider==account.ProviderId).ToArray();var rows=new List<TokenPeriod>();for(int i=boundaries.Length-2;i>=0;i--){long from=(long)(boundaries[i].ToUniversalTime()-new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero)).TotalMilliseconds,to=(long)(boundaries[i+1].ToUniversalTime()-new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero)).TotalMilliseconds;var values=records.Where(row=>row.Time>=from&&row.Time<to).ToArray();rows.Add(new TokenPeriod{Start=boundaries[i].ToString("o"),End=boundaries[i+1].ToString("o"),Tokens=values.Sum(row=>row.Total),Input=values.Sum(row=>row.Input),Output=values.Sum(row=>row.Output),CacheRead=values.Sum(row=>row.Read),CacheWrite=values.Sum(row=>row.Write),Reasoning=values.Sum(row=>row.Reasoning),Requests=values.Length,Cost=values.Sum(row=>row.Cost)});}return new HistoryWindow{AccountId=account.Id,Grain=query.Grain,Page=query.Page,Start=query.Start,End=query.End,Pages=pages,HasNext=query.Page+1<pages,Rows=rows.ToArray(),UpdatedAt=DateTimeOffset.UtcNow.ToString("o"),Complete=true};}
    public static string Executable(){var paths=new List<string>{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","@opencode-aidesktop","resources","opencode-cli.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".opencode","bin","opencode.exe")};foreach(string folder in (Environment.GetEnvironmentVariable("PATH")??"").Split(';'))if(!string.IsNullOrWhiteSpace(folder))paths.Add(Path.Combine(folder,"opencode.exe"));return paths.FirstOrDefault(File.Exists);}
    private async Task EnsureServer(){await serverGate.WaitAsync();try{if(server!=null&&!server.HasExited)return;string exe=Executable();if(exe==null)throw new InvalidOperationException("请先安装 OpenCode v2 官方客户端，再使用官方授权和账号切换");var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();string password=Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N");var info=new ProcessStartInfo(exe,"serve --hostname 127.0.0.1 --port "+port){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["OPENCODE_SERVER_PASSWORD"]=password;info.EnvironmentVariables["OPENCODE_SERVER_USERNAME"]="opencode";server=Process.Start(info);server.OutputDataReceived+=(s,e)=>{};server.ErrorDataReceived+=(s,e)=>{};server.BeginOutputReadLine();server.BeginErrorReadLine();local=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){BaseAddress=new Uri("http://127.0.0.1:"+port),Timeout=TimeSpan.FromSeconds(30)};local.DefaultRequestHeaders.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes("opencode:"+password)));for(int i=0;i<100;i++){if(server.HasExited)throw new InvalidOperationException("OpenCode 授权服务启动失败，请检查官方客户端版本");try{using(var response=await local.GetAsync("/api/credential")){if(response.IsSuccessStatusCode)return;}}catch(HttpRequestException){}await Task.Delay(100);}throw new InvalidOperationException("OpenCode 授权服务启动超时");}finally{serverGate.Release();}}
    public async Task<Dictionary<string,object>> Api(string path,string method="GET",object body=null){if(apiOverride!=null)return await apiOverride(path,method,body);if(disposed)throw new ObjectDisposedException("OpenCodeService");Interlocked.Increment(ref apiCalls);if(idleTimer!=null)idleTimer.Change(Timeout.Infinite,Timeout.Infinite);try{await EnsureServer();using(var request=new HttpRequestMessage(new HttpMethod(method),path)){if(body!=null)request.Content=new StringContent(new JavaScriptSerializer().Serialize(body),Encoding.UTF8,"application/json");using(var response=await local.SendAsync(request)){if(!response.IsSuccessStatusCode)throw new InvalidOperationException("OpenCode 官方服务 HTTP "+(int)response.StatusCode);string content=await response.Content.ReadAsStringAsync();return string.IsNullOrWhiteSpace(content)?new Dictionary<string,object>():new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<Dictionary<string,object>>(content);}}}finally{if(Interlocked.Decrement(ref apiCalls)==0&&!disposed)StartIdleTimer();}}
    public async Task<string> Switch(Account account,string value){ValidateProvider(account.ProviderId);var parsed=ParseValue(value);var credentials=credentialOverride==null?Credentials():credentialOverride();string backup=Path.Combine(backupDirectory,"opencode-before-switch.encrypted");Core.AtomicWrite(backup,Core.Encrypt(new JavaScriptSerializer().Serialize(credentials)));var found=credentials.FirstOrDefault(item=>item.Provider==account.ProviderId&&(!string.IsNullOrEmpty(account.OpenCodeCredentialId)&&item.Id==account.OpenCodeCredentialId||Fingerprint(item.Value)==Fingerprint(value)));string id=found==null?null:found.Id;if(string.IsNullOrEmpty(id)){var created=Core.Object(Core.Value(await Api("/api/credential","POST",new{integrationID=account.ProviderId,label=account.Name,value=parsed,activate=false}),"data"));id=Core.Text(created,"id");}if(string.IsNullOrWhiteSpace(id))throw new InvalidOperationException("官方客户端未返回凭据标识，已停止切换");await Api("/api/credential/"+Uri.EscapeDataString(id)+"/activate","POST");var selected=(credentialOverride==null?Credentials():credentialOverride()).FirstOrDefault(item=>item.Id==id&&item.Active);if(selected==null)throw new InvalidOperationException("切换结果未确认，请在 OpenCode 检查当前账号");return id;}
    public void Dispose(){disposed=true;if(idleTimer!=null)idleTimer.Dispose();StopServer();}
}
